// ---------------------------------------------------------------- the desktop
//
// What it keeps, in the layout's state (it goes along from scene to scene on a
// Pi, and is gone at a restart): `wins`, the windows open in the order they were
// opened, each {id, x, y, w, h, z, max, min, snap}, in the desktop's pixels (x to
// h is the window's own box, kept while it fills the desktop or is snapped to a
// half of it, `snap` 'l' or 'r'; a built-in scene's also its `title`); `boxes`,
// where each scene's window was when it closed, by scene id; `last`, the
// scene that had the focus at the last render; `asked`, the scene this layout last
// brought forward itself; `gone`, the scene whose window was just closed; `menu`,
// the menu open in the menu bar; `full`, `peek` and `drag`, a move or a size in
// progress.

const winsOf = (app) => (Array.isArray(app.state.wins) ? app.state.wins : [])
const topZ = (wins) => wins.reduce((z, w) => Math.max(z, w.z || 0), 0)

// What a window's frame takes around its scene: the border, the title bar and its
// rule, the strip at the bottom, and the rings under it on glass.
const chromeW = () => 2 * edge + (t.lift ? 2 * zoom : 0)
const chromeH = () => 3 * edge + Math.round(40 * zoom) + (t.lift ? 5 * zoom : 0)

function clamp(win, deskW, deskH) {
  const minW = Math.min(deskW, Math.round(160 * zoom))
  const minH = Math.min(deskH, Math.round(100 * zoom))
  win.w = Math.round(Math.max(minW, Math.min(win.w, deskW)))
  win.h = Math.round(Math.max(minH, Math.min(win.h, deskH)))
  // A title bar stays where the pointer can get at it.
  const grip = Math.round(48 * zoom)
  win.x = Math.round(Math.max(grip - win.w, Math.min(win.x, deskW - grip)))
  win.y = Math.round(Math.max(0, Math.min(win.y, deskH - Math.round(30 * zoom))))
  return win
}

const boxesOf = (app) => (app.state.boxes && typeof app.state.boxes === 'object' ? app.state.boxes : {})

// A closed window's box, for when its scene opens again.
function keep(app, win) {
  const { x, y, w, h, max, snap } = win
  frameos.setState('boxes', { ...boxesOf(app), [win.id]: { x, y, w, h, max, snap } })
}

// The scene's own area in a new window, from the layout's "Window size" (`WxH`, in
// a desktop's pixels like every size here); null for the whole desktop.
function ownSize(app) {
  const m = /^(\d+)x(\d+)$/.exec(String(app.state.windowSize || '800x480'))
  return m ? { w: Math.round(Number(m[1]) * zoom), h: Math.round(Number(m[2]) * zoom) } : null
}

function placed(app, id, wins, deskW, deskH) {
  const win = { id, z: topZ(wins) + 1 }
  // Where it was when it closed, if it was open before.
  const kept = boxesOf(app)[id]
  if (kept) return clamp({ ...kept, ...win }, deskW, deskH)
  // Otherwise the layout's size, its frame around it, cascading from the corner
  // and all of it on the desktop.
  const step = Math.round(28 * zoom) * (wins.length % 6)
  const size = ownSize(app)
  const w = size ? size.w + chromeW() : deskW + 1
  const h = size ? size.h + chromeH() : deskH + 1
  if (w <= deskW && h <= deskH) {
    const x = Math.min(Math.round(80 * zoom) + step, deskW - w)
    const y = Math.min(Math.round(16 * zoom) + step, deskH - h)
    return clamp({ ...win, x, y, w, h, max: false }, deskW, deskH)
  }
  // Where it does not fit, the first window fills the desktop, which is what the
  // frame looked like before anything else was opened, and the next ones take
  // most of it; set to the whole desktop, every one fills it.
  const shown = wins.filter((other) => !other.min).length
  const box = { x: Math.round(80 * zoom) + step, y: Math.round(16 * zoom) + step, w: deskW * 0.62, h: deskH * 0.62 }
  return clamp({ ...win, ...box, max: !size || shown === 0 }, deskW, deskH)
}

// What another desktop had open when this layout was chosen in its place (its
// `openScenes`, handed over by the runtime: docs/scene-layouts.md "Windows"): a
// window each, cascading in that order, so the one that had the focus is on top.
function opened(app, names, titleOf, deskW, deskH) {
  const wins = []
  for (const id of Array.isArray(app.state.openScenes) ? app.state.openScenes : []) {
    if (typeof id !== 'string' || wins.some((w) => w.id === id) || !(names[id] || isSystem(id))) continue
    const win = placed(app, id, wins, deskW, deskH)
    if (isSystem(id)) win.title = titleOf(id, names)
    wins.push(win)
  }
  return wins
}

// What is open, the one with the focus last: what a layout chosen in this one's
// place opens (`openScenes`).
function keepOpen(app, wins, current) {
  const order = wins
    .filter((w) => w.id !== current)
    .sort((a, b) => (a.z || 0) - (b.z || 0))
    .map((w) => w.id)
  if (wins.some((w) => w.id === current)) order.push(current)
  if (JSON.stringify(order) !== JSON.stringify(app.state.openScenes || [])) frameos.setState('openScenes', order)
}

// Where a window is drawn: its own box, the whole desktop, or a half of it.
function boxOf(win, deskW, deskH) {
  const half = Math.round(deskW / 2)
  if (win.max) return { x: 0, y: 0, w: deskW, h: deskH }
  if (win.snap === 'l') return { x: 0, y: 0, w: half, h: deskH }
  if (win.snap === 'r') return { x: half, y: 0, w: deskW - half, h: deskH }
  return { x: win.x, y: win.y, w: win.w, h: win.h }
}

// What a press, a key or a menu does to the windows. Each one reads the state
// afresh: a drag's moves come faster than renders.
function actions(app) {
  const current = app.frame.sceneId
  const update = (id, change) => {
    const next = winsOf(app).map((w) => (w.id === id ? { ...w, ...change(w) } : w))
    frameos.setState('wins', next)
  }
  // Every window this layout brings forward goes through here, so a built-in
  // scene that loses the focus some other way is known to have gone back.
  const go = (id) => {
    frameos.setState('asked', id)
    frameos.dispatch('setCurrentScene', { sceneId: id })
  }
  const focus = (id) => {
    frameos.setState('menu', null)
    update(id, () => ({ min: false }))
    if (id !== current) go(id)
  }
  const open = (id) => {
    frameos.setState('menu', null)
    if (winsOf(app).some((w) => w.id === id)) return focus(id)
    if (id !== current) go(id)
    else if (app.state.gone === id) frameos.setState('gone', null)
  }
  // Read when a handler runs, not when it was drawn: a press before it may have
  // brought another window forward.
  const showing = () => app.frame.sceneId
  const windowOf = (id) => winsOf(app).find((w) => w.id === id)
  // The scene window on top: what the menu bar's Settings is for, and what a
  // built-in scene opens over.
  const topScene = () =>
    winsOf(app)
      .filter((w) => !isSystem(w.id) && !w.min)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
  // A built-in scene opens over a scene. Over another built-in one, that one stays
  // open in its window, and the scene window on top comes forward to open it over;
  // with none, the built-in one goes back where it came from. Either way the
  // focus is this layout's doing (`asked`): the one left open keeps its window.
  const overAScene = () => {
    const now = showing()
    if (!isSystem(now)) return
    const top = topScene()
    if (top) go(top.id)
    else frameos.dispatch(commandOf(now))
  }
  // A scene's settings, from the gear on its title bar: a window of their own,
  // opened over the scene's window brought forward first; open already, that
  // window comes forward as it was left.
  const sceneSettings = (id) => {
    frameos.setState('menu', null)
    if (windowOf(settingsOf(id))) return focus(settingsOf(id))
    if (id !== showing()) go(id)
    frameos.dispatch('sceneSettings', {})
    frameos.setState('asked', settingsOf(id))
  }
  // The menu bar's Settings: the scene in front's, or the one on top under a
  // built-in scene's window.
  const frontSettings = () => {
    const now = showing()
    const id = isSystem(now) ? (topScene() || {}).id : now
    if (id) sceneSettings(id)
    else frameos.setState('menu', null)
  }
  // A built-in scene of the frame's, one window each: System Settings (the frame's
  // page: the mark's menu, the status icons, the Dock), Launchpad and Terminal.
  // Open already, it comes forward as it was left.
  const builtIn = (id, command, payload) => () => {
    frameos.setState('menu', null)
    if (windowOf(id)) return focus(id)
    overAScene()
    frameos.dispatch(command, payload)
    frameos.setState('asked', id)
  }
  const controlPanel = builtIn(SETTINGS, 'sceneSettings', { page: 'frame' })
  const launchpad = builtIn(SWITCHER, 'sceneSwitcher', {})
  const terminal = builtIn(TERMINAL, 'terminal', {})
  // The window in front went away: the next one down takes the focus.
  const nextAfter = (id) =>
    winsOf(app)
      .filter((w) => w.id !== id && !w.min)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
  const minimize = (id) => {
    frameos.setState('menu', null)
    update(id, () => ({ min: true }))
    const next = id === current ? nextAfter(id) : null
    if (next) go(next.id)
  }
  // A built-in scene with the focus closes as its own Cancel does, back to the
  // scene it was opened over.
  const close = (id) => {
    const next = id === current ? nextAfter(id) : null
    const win = winsOf(app).find((w) => w.id === id)
    if (win) keep(app, win)
    frameos.setState('wins', winsOf(app).filter((w) => w.id !== id))
    if (id !== current) return
    frameos.setState('gone', id)
    frameos.setState('full', false)
    if (isSystem(id)) frameos.dispatch(commandOf(id))
    else if (next) go(next.id)
  }
  const toggleMax = (id) => {
    frameos.setState('menu', null)
    update(id, (w) => ({ max: !w.max, snap: null }))
  }
  const toggleFull = () => {
    frameos.setState('menu', null)
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
  }
  // Alt+Tab: the window that had the focus before this one, so twice comes back;
  // with Shift, the one at the bottom, so every window comes round in turn.
  const cycle = (back) => {
    const others = winsOf(app)
      .filter((w) => w.id !== current)
      .sort((a, b) => (b.z || 0) - (a.z || 0))
    const next = back ? others[others.length - 1] : others[0]
    if (next) focus(next.id)
    return !!next
  }
  return {
    update, focus, open, sceneSettings, frontSettings, controlPanel, launchpad, terminal, minimize, close, toggleMax,
    toggleFull, cycle,
  }
}

// What a built-in scene's window is called before it has shown its page here.
const titleOf = (id, names) => {
  const scene = settingsFor(id)
  if (scene) return `${names[scene] || scene} Settings`
  return id === SWITCHER ? 'Launchpad' : id === TERMINAL ? 'Terminal' : 'System Settings'
}

// What a built-in scene's window is called, by the page it shows.
function systemTitle(app, names) {
  const scene = settingsFor(app.frame.sceneId)
  if (scene) return `${names[scene] || app.state.openedOver || scene} Settings`
  if (app.frame.sceneId === SWITCHER) return 'Launchpad'
  if (app.frame.sceneId === TERMINAL) return 'Terminal'
  const page = app.frame.sceneName
  if (page === 'Frame settings') return 'System Settings'
  if (page === 'Layout settings') return 'Desktop & Dock'
  return app.state.openedOver ? `${app.state.openedOver} Settings` : 'Settings'
}

function desktop(app, now, width, height, mono) {
  const scale = app.frame.scale || 1
  const builtIn = app.frame.systemScene === true
  const current = app.frame.sceneId
  const names = {}
  for (const scene of app.frame.scenes) names[scene.id] = scene.name || scene.id
  if (!builtIn && current && !names[current]) names[current] = app.frame.sceneName || current
  const store = storeOf(app)
  const assets = assetsOf(app)
  const programs = app.frame.scenes.filter((scene) => !isFrameApp(scene))
  // The Dock: Launchpad, every scene, a divider, the scene store and the asset
  // browser, System Settings and Terminal, its icons smaller where they would not
  // fit across.
  const docked = on(app.state.showDock)
  const count = app.frame.scenes.length + 3
  tile = Math.max(20, Math.min(46, Math.floor((width / zoom - 40) / count - 7)))
  const menuH = Math.round(26 * zoom)
  const dockH = docked ? Math.round((tile + 23) * zoom) + 2 * edge : 0
  const deskTop = menuH
  const deskW = width
  const deskH = Math.max(1, height - menuH - dockH)

  // Whatever brought a scene forward (a window, the Dock, a menu, the scene list, a
  // button, the API), its window is open and on top, and the one it took the
  // focus from is next below it. A built-in scene's window is named by what it
  // shows while it has the focus, and closes once it has gone back by itself: the
  // focus left it for a scene, and not because this layout moved it. One that
  // opened another (the gear in a scene's settings opening System Settings) did
  // not go back, and stays open.
  // A layout just chosen in another desktop's place has no windows of its own yet:
  // it opens what that one had open.
  const fresh = !Array.isArray(app.state.wins)
  const saved = fresh ? opened(app, names, titleOf, deskW, deskH) : winsOf(app)
  const wins = saved.filter((w) => w && (names[w.id] || isSystem(w.id)))
  let changed = fresh ? wins.length > 0 : wins.length !== saved.length
  if (current) {
    let win = wins.find((w) => w.id === current)
    if (!win && app.state.gone !== current) {
      win = placed(app, current, wins, deskW, deskH)
      wins.push(win)
      changed = true
    }
    if (win && builtIn && win.title !== systemTitle(app, names)) {
      win.title = systemTitle(app, names)
      changed = true
    }
    if (app.state.last !== current) {
      if (win && win.min) win.min = false
      const before = wins.find((w) => w.id === app.state.last)
      if (before && isSystem(before.id) && !isSystem(current) && app.state.asked !== current) {
        keep(app, before)
        wins.splice(wins.indexOf(before), 1)
      } else if (before) before.z = topZ(wins) + 1
      if (app.state.gone && app.state.gone !== current) frameos.setState('gone', null)
      if (app.state.asked) frameos.setState('asked', null)
      frameos.setState('last', current)
      changed = true
    }
  }
  if (changed) frameos.setState('wins', wins)
  keepOpen(app, wins, current)
  for (const win of wins) if (isSystem(win.id)) names[win.id] = win.title || titleOf(win.id, names)

  const focused = wins.find((w) => w.id === current && !w.min)
  const full = !!focused && on(app.state.full)
  const menu = app.state.menu || null
  const {
    update, focus, open, sceneSettings, frontSettings, controlPanel, launchpad, terminal, minimize, close, toggleMax,
    toggleFull,
  } = actions(app)

  // A press on a title bar moves the window, one on its edge sizes it from that
  // edge; the moves that follow are captured by what was pressed. Let go at the
  // top of the desktop, a moved window fills it, at the left or right edge it
  // takes that half; dragged away again, it has its own size back.
  const startDrag = (drawn, mode) => (e) => {
    // As it is now, not as it was drawn: a size may have come since.
    const win = winsOf(app).find((w) => w.id === drawn.id) || drawn
    const box = boxOf(win, deskW, deskH)
    const docked = !!(win.max || win.snap)
    // A half sized from its edge is a window of that size from then on.
    if (docked && mode !== 'move') update(win.id, () => ({ ...box, snap: null }))
    frameos.setState('drag', {
      id: win.id,
      mode,
      x: e.x,
      y: e.y,
      from: box,
      own: { w: win.w, h: win.h },
      docked: docked && mode === 'move',
      at: null,
    })
    if (win.id !== current) focus(win.id)
  }
  const dragTo = (e) => {
    const drag = app.state.drag
    if (!drag || !e.buttons) return
    const dx = (e.x - drag.x) / scale
    const dy = (e.y - drag.y) / scale
    if (drag.mode === 'move') {
      const x = e.x / scale
      const y = e.y / scale - deskTop
      const at = y <= 2 ? 'max' : x <= 2 ? 'l' : x >= deskW - 3 ? 'r' : null
      if (drag.docked) {
        // A press that does not move leaves it be (a double click sizes it back).
        if (Math.abs(dx) + Math.abs(dy) < 8 * zoom) return
        // Its own size, with the pointer as far across the title bar as it was.
        const across = (drag.x / scale - drag.from.x) / drag.from.w
        const from = { x: drag.x / scale - across * drag.own.w, y: drag.from.y, w: drag.own.w, h: drag.own.h }
        frameos.setState('drag', { ...drag, at, docked: false, from })
        update(drag.id, () => ({ ...clamp({ ...from, x: from.x + dx, y: from.y + dy }, deskW, deskH), max: false, snap: null }))
        return
      }
      if (at !== drag.at) frameos.setState('drag', { ...drag, at })
    }
    const f = drag.from
    update(drag.id, () => {
      const box = { ...f }
      if (drag.mode === 'move') {
        box.x = f.x + dx
        box.y = f.y + dy
      } else {
        if (drag.mode.includes('l')) {
          box.x = Math.min(f.x + dx, f.x + f.w - 80 * zoom)
          box.w = f.w - (box.x - f.x)
        }
        if (drag.mode.includes('r')) box.w = f.w + dx
        if (drag.mode.includes('t')) {
          box.y = Math.max(0, Math.min(f.y + dy, f.y + f.h - 60 * zoom))
          box.h = f.h - (box.y - f.y)
        }
        if (drag.mode.includes('b')) box.h = f.h + dy
      }
      return clamp(box, deskW, deskH)
    })
  }
  const endDrag = () => {
    const drag = app.state.drag
    frameos.setState('drag', null)
    if (drag && drag.mode === 'move' && drag.at && !drag.docked) {
      update(drag.id, () => (drag.at === 'max' ? { max: true, snap: null } : { max: false, snap: drag.at }))
    }
  }
  const corner = 14 * zoom
  const edgeOf = (e) => {
    const x = e.localX < corner ? 'l' : e.localX > e.width - corner ? 'r' : ''
    const y = e.localY < corner ? 't' : e.localY > e.height - corner ? 'b' : ''
    return y + x || 'b'
  }
  const sizing = (win) => ({
    onPointerDown: (e) => startDrag(win, edgeOf(e))(e),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
  })
  const moving = (win) => ({
    onPointerDown: startDrag(win, 'move'),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
    onDoubleClick: () => toggleMax(win.id),
  })

  const windowOf = (win) => {
    const active = win.id === current
    const box = boxOf(win, deskW, deskH)
    return (
      <div
        className={`absolute left-[${box.x}px] top-[${box.y}px] w-[${box.w}px] h-[${box.h}px] flex flex-col`}
        {...(win.max ? {} : sizing(win))}
      >
        <Lifted>
          <div className={`flex flex-col flex-1 min-h-0 rounded-[${px(11)}] border-[${edge}px] ${t.window}`}>
            <div className={`flex items-center shrink-0 h-[${px(30)}] px-[${px(8)}]`} {...moving(win)}>
              <Lights
                dim={!active}
                onClose={() => close(win.id)}
                onMinimize={() => minimize(win.id)}
                onZoom={() => toggleMax(win.id)}
              />
              <span className={`shrink min-w-0 truncate font-semibold ${active ? t.title : t.faint}`}>{names[win.id]}</span>
              <div className="flex flex-1 basis-0 min-w-0 justify-end">
                {isSystem(win.id) ? null : <GearButton active={active} onClick={() => sceneSettings(win.id)} />}
              </div>
            </div>
            <div className={`shrink-0 h-[${edge}px] ${t.rule}`} />
            <div className="relative flex flex-col flex-1 min-h-0">
              {active ? <yield /> : <Scene id={win.id} />}
              {/* A press on a window behind brings it forward, and is only that. */}
              {active ? null : <div className="absolute inset-0" onPointerDown={() => focus(win.id)} />}
            </div>
            <div className={`shrink-0 h-[${px(10)}]`} />
          </div>
        </Lifted>
      </div>
    )
  }

  // Where a window let go now would go: a rounded outline over the windows.
  const outline = () => {
    const drag = app.state.drag
    if (!drag || drag.mode !== 'move' || !drag.at || drag.docked) return null
    const b = boxOf({ max: drag.at === 'max', snap: drag.at }, deskW, deskH)
    const inset = Math.round(4 * zoom)
    return (
      <div
        className={`absolute left-[${b.x + inset}px] top-[${b.y + inset}px] w-[${b.w - 2 * inset}px] h-[${b.h - 2 * inset}px] rounded-[${px(11)}] border-[${Math.max(2, edge * 2)}px] ${t.outline}`}
      />
    )
  }

  // The menu bar, over everything: the mark's menu, the name of the window in
  // front, Scenes, Settings and Window, and the status icons with the clock. A
  // menu open goes over to another title the pointer moves onto.
  const menuBar = () => {
    const toggle = (id) => () => frameos.setState('menu', menu === id ? null : id)
    const slide = (id) => (menu && menu !== id ? () => frameos.setState('menu', id) : undefined)
    const Item = ({ onClick, children }) => (
      <div
        className={`flex items-center gap-[${px(8)}] h-[${px(24)}] mx-[${px(5)}] px-[${px(9)}] rounded-[${px(5)}] whitespace-nowrap ${t.pick}`}
        onClick={onClick}
      >
        {children}
      </div>
    )
    const Rule = () => <div className={`shrink-0 h-[${edge}px] mx-[${px(10)}] my-[${px(4)}] ${t.rule}`} />
    // A menu takes a press itself: the cover under it closes the menu on a press,
    // and a render before the release would take the item away from the click.
    const Drop = ({ w, children }) => (
      <div
        className={`absolute left-0 top-[${px(24)}] w-[${Math.round(w * zoom)}px] max-h-[${deskH + dockH - Math.round(4 * zoom)}px] flex flex-col py-[${px(5)}] rounded-[${px(8)}] border-[${edge}px] overflow-y-auto ${t.drop}`}
        onPointerDown={() => {}}
      >
        {children}
      </div>
    )
    const Dot = ({ shown }) => (
      <div className={`shrink-0 w-[${px(6)}] h-[${px(6)}] rounded-full ${shown ? t.dot : ''}`} />
    )
    return (
      <div
        className={`absolute left-0 top-0 w-full h-[${menuH}px] flex items-center px-[${px(6)}] ${t.menu} ${
          t.ruled ? `border-b-[${edge}px] border-black` : ''
        }`}
      >
        <Menu lit={menu === 'mark'} onClick={toggle('mark')} onPointerMove={slide('mark')}>
          <Mark />
          {menu === 'mark' ? (
            <Drop w={210}>
              <Item onClick={controlPanel}>System Settings…</Item>
              {store ? <Item onClick={() => open(store.id)}>Scene Store…</Item> : null}
              <Item onClick={launchpad}>Launchpad</Item>
              <Item onClick={terminal}>Terminal</Item>
            </Drop>
          ) : null}
        </Menu>
        <span className={`shrink min-w-0 truncate font-bold px-[${px(8)}]`}>{names[current] || 'FrameOS'}</span>
        <Menu lit={menu === 'scenes'} onClick={toggle('scenes')} onPointerMove={slide('scenes')}>
          Scenes
          {menu === 'scenes' ? (
            <Drop w={230}>
              {programs.map((scene) => (
                <Item onClick={() => open(scene.id)}>
                  <Dot shown={wins.some((w) => w.id === scene.id)} />
                  <span className="flex-1 truncate">{names[scene.id]}</span>
                </Item>
              ))}
              <Rule />
              {[store, assets].filter(Boolean).map((scene) => (
                <Item onClick={() => open(scene.id)}>
                  <Dot shown={wins.some((w) => w.id === scene.id)} />
                  <span className="flex-1 truncate">{names[scene.id]}</span>
                </Item>
              ))}
              <Item onClick={launchpad}>
                <Dot shown={false} />
                Launchpad
              </Item>
            </Drop>
          ) : null}
        </Menu>
        <Menu onClick={frontSettings} onPointerMove={slide(null)}>
          Settings
        </Menu>
        <Menu lit={menu === 'window'} onClick={toggle('window')} onPointerMove={slide('window')}>
          Window
          {menu === 'window' ? (
            <Drop w={230}>
              {focused ? (
                <Item onClick={() => minimize(focused.id)}>
                  <Dot shown={false} />
                  Minimize
                </Item>
              ) : null}
              {focused ? (
                <Item onClick={() => toggleMax(focused.id)}>
                  <Dot shown={false} />
                  Zoom
                </Item>
              ) : null}
              {focused ? (
                <Item onClick={toggleFull}>
                  <Dot shown={false} />
                  {full ? 'Exit Full Screen' : 'Enter Full Screen'}
                </Item>
              ) : null}
              {focused ? <Rule /> : null}
              {wins.map((win) => (
                <Item onClick={() => focus(win.id)}>
                  <Dot shown={win.id === current} />
                  <span className={`flex-1 truncate ${win.min ? 'italic' : ''}`}>{names[win.id]}</span>
                </Item>
              ))}
            </Drop>
          ) : null}
        </Menu>
        <div className="flex-1" />
        <Menu onClick={controlPanel} onPointerMove={slide(null)}>
          <Toggles />
          <Wifi rssi={app.frame.wifiRssi} />
          <Battery percent={app.frame.batteryPercent} mono={mono} />
          {width >= 640 * Math.max(zoom, 1) ? <span>{`${DAYS[now.getDay()]} ${now.getDate()} ${MONTHS[now.getMonth()]}`}</span> : null}
          <span>{clock(now, on(app.state.twentyFourHour))}</span>
        </Menu>
      </div>
    )
  }

  // The Dock, along the bottom: Launchpad, the frame's scenes with a dot under the
  // ones open, then the scene store, System Settings and Terminal.
  const dock = () => {
    const isOpen = (id) => wins.some((w) => w.id === id)
    return (
      <div className={`absolute left-0 bottom-0 w-full h-[${dockH}px] flex justify-center items-start`}>
        <div
          className={`flex items-end gap-[${px(7)}] mt-[${px(2)}] px-[${px(7)}] pt-[${px(6)}] pb-[${px(3)}] rounded-[${px(18)}] border-[${edge}px] ${t.dock}`}
        >
          <DockItem open={isOpen(SWITCHER)} onClick={launchpad}>
            <ScenesIcon mono={mono} />
          </DockItem>
          {programs.map((scene, i) => (
            <DockItem open={isOpen(scene.id)} onClick={() => open(scene.id)}>
              <SceneIcon name={names[scene.id]} colors={SCENE_TILES[i % SCENE_TILES.length]} />
            </DockItem>
          ))}
          <div className={`self-stretch w-[${edge}px] mx-[${px(2)}] mb-[${px(7)}] ${t.divider}`} />
          {store ? (
            <DockItem open={isOpen(store.id)} onClick={() => open(store.id)}>
              <StoreTile mono={mono} />
            </DockItem>
          ) : null}
          {assets ? (
            <DockItem open={isOpen(assets.id)} onClick={() => open(assets.id)}>
              <AssetsTile mono={mono} />
            </DockItem>
          ) : null}
          <DockItem open={isOpen(SETTINGS)} onClick={controlPanel}>
            <SettingsIcon mono={mono} />
          </DockItem>
          <DockItem open={isOpen(TERMINAL)} onClick={terminal}>
            <TerminalIcon mono={mono} />
          </DockItem>
        </div>
      </div>
    )
  }

  const cover = menu ? (
    <div className="absolute inset-0" onPointerDown={() => frameos.setState('menu', null)} onClick={() => {}} />
  ) : null

  if (full) {
    // The panel is the window's. The pointer at the top edge brings the menu bar;
    // moved back over the window, it goes again, unless a menu is open.
    const peek = on(app.state.peek) || !!menu
    return (
      <div className={`relative w-full h-full bg-black text-[${px(14)}]`}>
        <div className="absolute inset-0 flex flex-col">
          <yield />
        </div>
        {!peek ? (
          <div className="absolute left-0 top-0 w-full h-[2px]" onPointerMove={() => frameos.setState('peek', true)} />
        ) : menu ? null : (
          <div
            className={`absolute left-0 top-[${menuH}px] w-full h-[${Math.max(1, height - menuH)}px]`}
            onPointerMove={() => frameos.setState('peek', false)}
          />
        )}
        {cover}
        {peek ? menuBar() : null}
      </div>
    )
  }

  const shown = wins.filter((w) => !w.min && !(focused && w.id === focused.id)).sort((a, b) => (a.z || 0) - (b.z || 0))
  if (focused) shown.push(focused)
  return (
    <div className={`relative w-full h-full text-[${px(14)}]`}>
      <Wallpaper mono={mono} w={Math.round(width)} h={Math.round(height)} />
      <div className={`absolute left-0 top-[${deskTop}px] w-[${deskW}px] h-[${deskH}px]`}>
        {shown.map(windowOf)}
        {outline()}
      </div>
      {docked ? dock() : null}
      {cover}
      {menuBar()}
    </div>
  )
}

// F11 gives the panel to the window in front and takes it back; Escape closes a
// menu and leaves the full screen; Alt+Tab (or Cmd+Tab) brings the window before
// forward (Shift: the one at the bottom), Alt+F4 or Cmd+W closes the one in front
// and Cmd+M puts it away. The scene heard the key first.
export function onEvent(app, context) {
  if (context.event !== 'keyDown' || !Array.isArray(app.frame.scenes) || !windowsOn(app)) return false
  const payload = context.payload || {}
  const key = payload.key
  if (key === 'F11') {
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
    return true
  }
  if (key === 'Escape' && (app.state.menu || on(app.state.full))) {
    frameos.setState('menu', null)
    frameos.setState('full', false)
    return true
  }
  const alt = payload.alt === true
  const cmd = payload.meta === true
  if (key === 'Tab' && (alt || cmd)) return actions(app).cycle(payload.shift === true)
  if (!app.frame.sceneId) return false
  if ((key === 'F4' && alt) || ((key === 'w' || key === 'W') && cmd)) {
    actions(app).close(app.frame.sceneId)
    return true
  }
  if ((key === 'm' || key === 'M') && cmd) {
    actions(app).minimize(app.frame.sceneId)
    return true
  }
  return false
}

const windowsOn = (app) => app.state.windows !== false && app.state.windows !== 'false'

export function get(app) {
  // app.frame's size is the panel's over the render scale, before the frame's rotation.
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = turned ? app.frame.height : app.frame.width
  const height = turned ? app.frame.width : app.frame.height
  const shortSide = Math.min(app.frame.width, app.frame.height)
  zoom = shortSide >= (app.frame.paper ? 1000 : 2160) ? 2 : shortSide >= 480 ? 1 : shortSide / 480
  edge = Math.max(1, Math.round(zoom))
  tile = 46
  const mono = app.frame.color === false
  t = mono ? MONO : app.frame.paper ? PAPER : GLASS
  const now = new Date()
  dress(app, THEMES, 'light')
  // The clock changes on the minute: nothing to draw until then.
  frameos.setNextSleep(60 - now.getSeconds())
  if (Array.isArray(app.frame.scenes) && windowsOn(app)) return desktop(app, now, width, height, mono)
  // One scene at a time: nothing else is open, nothing for another layout to open.
  if (Array.isArray(app.state.openScenes) && app.state.openScenes.length) frameos.setState('openScenes', [])
  // The date and the Window menu need room: the scene's name gives way first.
  const roomy = width >= 640 * Math.max(zoom, 1)
  const name = app.frame.sceneName || 'FrameOS'
  const builtIn = app.frame.systemScene === true
  // The terminal (not on an ESP32, where app.frame.sceneId is not there either).
  const terminalOpen = builtIn && app.frame.sceneId === TERMINAL
  const settingsOpen = builtIn && !terminalOpen && name.includes('settings')
  const frameOpen = settingsOpen && name.startsWith('Frame')
  const listOpen = builtIn && !settingsOpen && !terminalOpen
  // The scene a built-in one opened over keeps its icon in the Dock.
  const scene = builtIn ? app.state.openedOver || '' : name
  const title = terminalOpen ? 'Terminal' : listOpen ? 'Launchpad' : frameOpen ? 'System Settings' : settingsOpen ? 'Settings' : name
  const minimized = !builtIn && app.state.minimized === true
  const zoomed = app.state.zoomed === true
  const framed = on(app.state.showWindow) && !zoomed
  const docked = on(app.state.showDock)
  // A built-in scene's own command, again, goes back to the scene it opened over.
  const closeBuiltIn = () => frameos.dispatch(terminalOpen ? 'terminal' : settingsOpen ? 'sceneSettings' : 'sceneSwitcher')
  const openList = () => frameos.dispatch('sceneSwitcher', { swap: true })
  const openSettings = () => frameos.dispatch('sceneSettings')
  const openFrame = () => frameos.dispatch('sceneSettings', { page: 'frame' })
  const toggleZoom = () => frameos.setState('zoomed', !zoomed)
  const showScene = builtIn
    ? closeBuiltIn
    : minimized
    ? () => frameos.setState('minimized', false)
    : zoomed
    ? toggleZoom
    : () => frameos.setState('minimized', true)
  return (
    <div className="relative w-full h-full">
      <Wallpaper mono={mono} w={Math.round(width)} h={Math.round(height)} />
      <div className={`absolute inset-0 flex flex-col text-[${px(14)}]`}>
        <div className={`flex items-center shrink-0 h-[${px(26)}] px-[${px(6)}] ${t.menu} ${t.ruled ? `border-b-[${edge}px] border-black` : ''}`}>
          <Menu onClick={openFrame}>
            <Mark />
          </Menu>
          <span className={`shrink min-w-0 truncate font-bold px-[${px(8)}]`}>{title}</span>
          <Menu onClick={openList}>Scenes</Menu>
          <Menu onClick={openSettings}>Settings</Menu>
          {roomy ? <Menu onClick={minimized ? showScene : toggleZoom}>Window</Menu> : null}
          <div className="flex-1" />
          <Menu onClick={openFrame}>
            <Toggles />
            <Wifi rssi={app.frame.wifiRssi} />
            <Battery percent={app.frame.batteryPercent} mono={mono} />
            {roomy ? <span>{`${DAYS[now.getDay()]} ${now.getDate()} ${MONTHS[now.getMonth()]}`}</span> : null}
            <span>{clock(now, on(app.state.twentyFourHour))}</span>
          </Menu>
        </div>
        {minimized ? (
          <div className="flex-1" />
        ) : framed ? (
          <div className={`flex flex-col flex-1 min-h-0 px-[${px(18)}] pt-[${px(12)}] ${docked ? `pb-[${px(6)}]` : `pb-[${px(18)}]`}`}>
            <Lifted>
              <Window
                title={title}
                onClose={builtIn ? closeBuiltIn : () => frameos.dispatch('sceneSwitcher')}
                onMinimize={builtIn ? closeBuiltIn : () => frameos.setState('minimized', true)}
                onZoom={toggleZoom}
              >
                <yield />
              </Window>
            </Lifted>
          </div>
        ) : (
          <yield />
        )}
        {docked ? (
          <div className={`flex items-end self-center shrink-0 gap-[${px(7)}] mt-[${px(2)}] mb-[${px(5)}] px-[${px(7)}] pt-[${px(6)}] pb-[${px(3)}] rounded-[${px(18)}] border-[${edge}px] ${t.dock}`}>
            <DockItem open={listOpen} onClick={openList}>
              <ScenesIcon mono={mono} />
            </DockItem>
            <DockItem open={settingsOpen && !frameOpen} onClick={openSettings}>
              <SettingsIcon mono={mono} />
            </DockItem>
            <DockItem open={frameOpen} onClick={openFrame}>
              <FrameIcon mono={mono} />
            </DockItem>
            {scene ? <div className={`self-stretch w-[${edge}px] mx-[${px(2)}] mb-[${px(7)}] ${t.divider}`} /> : null}
            {scene ? (
              <DockItem open={true} onClick={showScene}>
                <SceneIcon name={scene} />
              </DockItem>
            ) : null}
          </div>
        ) : null}
      </div>
    </div>
  )
}
